package passkey

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"testing"
	"time"

	identity "github.com/faustbrian/go-identity"
	"github.com/faustbrian/go-identity/session"
	webauthn "github.com/faustbrian/go-webauthn"
)

// Only the protocol's explicit storage seam is substituted. Options, challenge
// custody and browser JSON are generated by the actual public protocol owner.
type conditionalOptionsStore struct{ webauthn.DiscoverableStore }

func (conditionalOptionsStore) CreateCeremony(ctx context.Context, creation webauthn.CeremonyCreation) (webauthn.CeremonyRecord, webauthn.Challenge, identity.CommitOutcome, error) {
	record, challenge, err := creation.Generate(ctx, time.Now().UTC())
	return record, challenge, identity.CommitOutcomeCommitted, err
}

func conditionalProtocolOptions(t *testing.T, identified bool) webauthn.AssertionOptions {
	t.Helper()
	key, err := webauthn.NewChallengeDigestKey(bytes.Repeat([]byte{1}, 32))
	if err != nil {
		t.Fatal(err)
	}
	protocol, err := webauthn.NewDiscoverable(webauthn.Config{TenantID: "tenant", RelyingParty: webauthn.RelyingParty{ID: "example.com", Name: "Example", Origins: []string{"https://example.com"}, Version: 1}, ChallengeKey: key, MaximumDuration: time.Second}, webauthn.Dependencies{Store: conditionalOptionsStore{}})
	if err != nil {
		t.Fatal(err)
	}
	command, err := identity.NewCommandID()
	if err != nil {
		t.Fatal(err)
	}
	c := webauthn.CeremonyContext{CommandID: command, TenantID: "tenant", ActorID: "service", AnonymousFlowID: "original-flow", CorrelationID: "correlation"}
	if identified {
		c.UserID, c.AnonymousFlowID = "user", ""
		ordinary, err := webauthn.New(webauthn.Config{TenantID: "tenant", RelyingParty: webauthn.RelyingParty{ID: "example.com", Name: "Example", Origins: []string{"https://example.com"}, Version: 1}, ChallengeKey: key, MaximumDuration: time.Second}, webauthn.Dependencies{Store: conditionalOptionsStore{}})
		if err != nil {
			t.Fatal(err)
		}
		options, err := ordinary.BeginAssertion(context.Background(), webauthn.BeginAssertionRequest{Context: c, Origin: "https://example.com", UserHandle: bytes.Repeat([]byte{2}, 32), AllowedCredentials: [][]byte{{3}}})
		if err != nil {
			t.Fatal(err)
		}
		return options
	}
	options, err := protocol.BeginDiscoverableAssertion(context.Background(), webauthn.BeginDiscoverableAssertionRequest{Context: c, Origin: "https://example.com"})
	if err != nil {
		t.Fatal(err)
	}
	return options
}

func TestConditionalOptionsProjectMediationWithoutChangingProtocolCustody(t *testing.T) {
	native := conditionalProtocolOptions(t, false)
	options, err := NewConditionalAssertionOptions(native)
	if err != nil {
		t.Fatal(err)
	}
	original, _ := native.Ceremony()
	got, ok := options.Ceremony()
	if !ok || got.ID != original.ID || got.ExpiresAt != original.ExpiresAt || got.Intent.Context != original.Intent.Context {
		t.Fatal("projection changed original ceremony scope or expiry")
	}
	var borrowed []byte
	if err := options.TransferJSON(context.Background(), func(_ context.Context, wire []byte) error {
		borrowed = wire
		var doc struct {
			Mediation string                     `json:"mediation"`
			PublicKey map[string]json.RawMessage `json:"publicKey"`
		}
		if err := json.Unmarshal(wire, &doc); err != nil {
			return err
		}
		if doc.Mediation != "conditional" || string(doc.PublicKey["userVerification"]) != `"required"` || string(doc.PublicKey["rpId"]) != `"example.com"` || len(doc.PublicKey["challenge"]) == 0 {
			t.Fatal("conditional projection changed native protocol requirements")
		}
		if _, present := doc.PublicKey["allowCredentials"]; present {
			t.Fatal("conditional options exposed account descriptors")
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	if len(borrowed) == 0 || !bytes.Equal(borrowed, make([]byte, len(borrowed))) {
		t.Fatal("borrowed challenge JSON not cleared")
	}
	for _, transfer := range []func(context.Context, func(context.Context, []byte) error) error{options.TransferJSON, native.TransferJSON} {
		if err := transfer(context.Background(), func(context.Context, []byte) error { t.Fatal("challenge disclosed twice"); return nil }); err == nil {
			t.Fatal("alias permitted repeat reveal")
		}
	}
}

func TestConditionalOptionsFailClosedAndKeepOneRevealAfterDeliveryFailure(t *testing.T) {
	if _, err := NewConditionalAssertionOptions(webauthn.AssertionOptions{}); !errors.Is(err, ErrInvalidInput) {
		t.Fatal("zero options accepted", err)
	}
	if _, err := NewConditionalAssertionOptions(conditionalProtocolOptions(t, true)); !errors.Is(err, ErrInvalidInput) {
		t.Fatal("identified protocol options reinterpreted", err)
	}
	var zero ConditionalAssertionOptions
	if err := zero.TransferJSON(context.Background(), func(context.Context, []byte) error { t.Fatal("zero emitted options"); return nil }); err == nil {
		t.Fatal("zero accepted")
	}
	native := conditionalProtocolOptions(t, false)
	options, err := NewConditionalAssertionOptions(native)
	if err != nil {
		t.Fatal(err)
	}
	if err := options.TransferJSON(context.Background(), nil); err == nil {
		t.Fatal("nil receiver accepted")
	}
	want := errors.New("controlled delivery failure")
	var unavailable webauthn.Unavailable
	if err := options.TransferJSON(context.Background(), func(context.Context, []byte) error { return want }); !errors.As(err, &unavailable) {
		t.Fatal("native delivery-failure redaction changed", err)
	}
	if err := native.TransferJSON(context.Background(), func(context.Context, []byte) error { t.Fatal("failed transfer restored challenge"); return nil }); err == nil {
		t.Fatal("failed transfer permitted reveal")
	}
	for _, value := range []any{options, KeyedConditionalOptionsResult{CommandID: "private-command", Options: options}} {
		for _, verb := range []string{"%v", "%+v", "%#v"} {
			if strings.Contains(fmt.Sprintf(verb, value), "private-") {
				t.Fatal("private correlation leaked")
			}
		}
		if wire, err := json.Marshal(value); len(wire) != 0 || !errors.Is(err, session.ErrSecretSerialization) {
			t.Fatal("implicit serialization accepted", err)
		}
	}
}
